import java.awt.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.swing.*;
import javax.swing.table.*;

/** Structured edits commit back to the same raw request, with a single source of truth. */
final class RequestInspector extends JTabbedPane {
    final VulnApp app;final DefaultTableModel params=new DefaultTableModel(new String[]{"Name","Value"},0),headers=new DefaultTableModel(new String[]{"Name","Value"},0),cookies=new DefaultTableModel(new String[]{"Name","Value"},0);final JTextArea body=VulnApp.area(true);boolean refreshing;
    RequestInspector(VulnApp app){this.app=app;addTab("Request",RequestWorkbench.editor(app.repeaterRequest));addTab("Params",table(params,"Params"));addTab("Headers",table(headers,"Headers"));addTab("Cookies",table(cookies,"Cookies"));JPanel content=new JPanel(new BorderLayout());content.add(VulnApp.bar(VulnApp.button("Apply body",()->commit("Body")),VulnApp.button("Validate / format JSON",()->{try{body.setText(RequestWorkbench.pretty(Json.write(Json.parse(body.getText()))));}catch(Exception ex){app.error(ex);}})),BorderLayout.NORTH);content.add(new JScrollPane(body));addTab("Body",content);addChangeListener(e->refresh());app.repeaterRequest.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){public void insertUpdate(javax.swing.event.DocumentEvent e){SwingUtilities.invokeLater(()->refresh());}public void removeUpdate(javax.swing.event.DocumentEvent e){SwingUtilities.invokeLater(()->refresh());}public void changedUpdate(javax.swing.event.DocumentEvent e){}});refresh();}
    JPanel table(DefaultTableModel model,String kind){JPanel p=VulnApp.page();JTable table=new JTable(model);table.putClientProperty("terminateEditOnFocusLost",true);p.add(VulnApp.bar(VulnApp.button("Add row",()->model.addRow(new Object[]{"",""})),VulnApp.button("Remove row",()->{int row=table.getSelectedRow();if(row>=0)model.removeRow(row);}),VulnApp.button("Apply "+kind,()->{if(table.isEditing())table.getCellEditor().stopCellEditing();commit(kind);})),BorderLayout.NORTH);p.add(new JScrollPane(table));return p;}
    static String decode(String s){try{return URLDecoder.decode(s,StandardCharsets.UTF_8);}catch(Exception ex){return s;}}
    void refresh(){if(refreshing)return;refreshing=true;try{VulnApp.Packet packet=VulnApp.parse(app.repeaterRequest.getText().getBytes(VulnApp.WIRE));params.setRowCount(0);int at=packet.target().indexOf('?');if(at>=0)for(String item:packet.target().substring(at+1).split("&")){String[] p=item.split("=",2);params.addRow(new Object[]{decode(p[0]),decode(p.length>1?p[1]:"")});}headers.setRowCount(0);packet.headers().forEach((k,v)->headers.addRow(new Object[]{k,v}));cookies.setRowCount(0);for(String item:packet.header("Cookie").split(";")){int equals=item.indexOf('=');if(equals>0)cookies.addRow(new Object[]{item.substring(0,equals).strip(),item.substring(equals+1).strip()});}body.setText(new String(packet.body(),StandardCharsets.UTF_8));}catch(Exception ignored){}finally{refreshing=false;}}
    void commit(String kind){try{VulnApp.Packet p=VulnApp.parse(app.repeaterRequest.getText().getBytes(VulnApp.WIRE));switch(kind){case "Params"->{StringBuilder query=new StringBuilder();for(int i=0;i<params.getRowCount();i++){if(i>0)query.append('&');query.append(URLEncoder.encode(Objects.toString(params.getValueAt(i,0),""),StandardCharsets.UTF_8)).append('=').append(URLEncoder.encode(Objects.toString(params.getValueAt(i,1),""),StandardCharsets.UTF_8));}String path=p.target().split("\\?",2)[0];p=new VulnApp.Packet(p.method(),path+(query.isEmpty()?"":"?"+query),p.protocol(),p.headers(),p.body());}case "Headers"->{LinkedHashMap<String,String> h=new LinkedHashMap<>();for(int i=0;i<headers.getRowCount();i++){String name=Objects.toString(headers.getValueAt(i,0),"").strip(),value=Objects.toString(headers.getValueAt(i,1),"");if(name.isEmpty())continue;NetworkPolicy.header(p,name,value);if(h.keySet().stream().anyMatch(k->k.equalsIgnoreCase(name)))throw new IllegalArgumentException("Duplicate header: "+name);h.put(name,value);}p=new VulnApp.Packet(p.method(),p.target(),p.protocol(),h,p.body());}case "Cookies"->{StringJoiner value=new StringJoiner("; ");for(int i=0;i<cookies.getRowCount();i++){String name=Objects.toString(cookies.getValueAt(i,0),"").strip(),v=Objects.toString(cookies.getValueAt(i,1),"");if(!name.matches("[!#$%&'*+.^_`|~0-9A-Za-z-]+")||v.contains(";")||v.contains("\r")||v.contains("\n"))throw new IllegalArgumentException("Invalid cookie row");value.add(name+"="+v);}p=NetworkPolicy.header(p,"Cookie",value.toString());}case "Body"->{p=new VulnApp.Packet(p.method(),p.target(),p.protocol(),p.headers(),body.getText().getBytes(StandardCharsets.UTF_8));p=NetworkPolicy.header(p,"Transfer-Encoding","");p=NetworkPolicy.header(p,"Content-Length",""+p.body().length);}default->throw new IllegalArgumentException(kind);}byte[] raw=VulnApp.serialize(p);VulnApp.parse(raw);app.repeaterRequest.setText(new String(raw,VulnApp.WIRE));refresh();}catch(Exception ex){app.error(ex);}}
}
